import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import './Login.css';


export default function Login() {
const [email, setEmail] = useState('');
const [password, setPassword] = useState('');
const [error, setError] = useState('');
const navigate = useNavigate();


function handleSubmit(e) {
e.preventDefault();
// Simple client-side "users" store (demo only)
const usersJson = localStorage.getItem('users');
const users = usersJson ? JSON.parse(usersJson) : [];
const found = users.find(u => u.email === email && u.password === password);
if (!found) {
setError('Invalid email or password. Or sign up first.');
return;
}
// create a fake token and save
const token = btoa(email + ':' + Date.now());
localStorage.setItem('authToken', token);
localStorage.setItem('currentUser', JSON.stringify({ email }));
navigate('/'); // go to dashboard
}


return (
<div className="auth-page">
<div className="auth-left">
<div className="brand">SoftScale</div>
<div className="auth-hero">
<h1>Welcome back</h1>
<p>Sign in to continue to your dashboard</p>
</div>
</div>


<div className="auth-card">
<div className="auth-card-inner">
<h2 className="card-title">Login</h2>


<form onSubmit={handleSubmit} className="auth-form">
<label className="label">Email</label>
<input className="input" value={email} onChange={e => setEmail(e.target.value)} required type="email" />


<label className="label">Password</label>
<input className="input" value={password} onChange={e => setPassword(e.target.value)} required type="password" />


{error && <div className="error">{error}</div>}


<button className="btn" type="submit">Log in</button>
</form>


<div className="signup-line">
Don't have an account? <Link to="/signup" className="link">Create one</Link>
</div>
</div>
</div>
</div>
);
}
